gTI(){return"\u0416\u043e\u049b. \u049a\u044b\u0437\u043c\u0435\u0442 \u043a\u04e9\u0440\u0441\u0435\u0442\u0443 \u0431\u0435\u043b\u0433\u0456\u043b\u0435\u0440\u0456 \u0436\u044b\u043b\u0434\u0430\u043c\u0434\u044b\u049b\u0442\u044b \u0448\u0435\u043a\u0442\u0435\u043c\u0435\u0439\u0434\u0456."},
gTL(){return"\u0411\u0435\u043b\u0433\u0456 \u0436\u0430\u043d\u0430\u0440\u043c\u0430\u0439 \u049b\u04b1\u044e \u0441\u0442\u0430\u043d\u0446\u0438\u044f\u0441\u044b\u043d \u043a\u04e9\u0440\u0441\u0435\u0442\u0435 \u043c\u0435?"},
gTK(){return"\u0418\u04d9. \u0411\u0435\u043b\u0433\u0456 \u0436\u0430\u043d\u0430\u0440\u043c\u0430\u0439 \u049b\u04b1\u044e \u0441\u0442\u0430\u043d\u0446\u0438\u044f\u0441\u044b\u043d \u043a\u04e9\u0440\u0441\u0435\u0442\u0435\u0434\u0456."},
gTN(){return"\u0411\u04b1\u043b \u0431\u0435\u043b\u0433\u0456 \u0436\u0430\u043d\u0430\u0440\u043c\u0430\u0439 \u049b\u04b1\u044e \u0431\u0435\u043a\u0435\u0442\u0456\u043d\u0435\u043d \u0436\u043e\u043b\u0434\u0430 \u049b\u0430\u043b\u0434\u044b\u0440\u0493\u0430\u043d\u0434\u0430 \u0431\u0430\u0441\u044b\u043c\u0434\u044b\u049b \u0431\u0435\u0440\u0435 \u043c\u0435?"},
gTM(){return"\u0416\u043e\u049b. \u041a\u04e9\u0440\u0448\u0456 \u0430\u0443\u043c\u0430\u049b\u0442\u0430\u043d \u0448\u044b\u049b\u049b\u0430\u043d \u043a\u0435\u0437\u0434\u0435 \u0436\u043e\u043b \u049b\u043e\u0437\u0493\u0430\u043b\u044b\u0441\u044b\u043d\u0430 \u049b\u0430\u0442\u044b\u0441\u0443\u0448\u044b\u043b\u0430\u0440\u0493\u0430 \u0436\u043e\u043b \u0431\u0435\u0440\u0443 \u043a\u0435\u0440\u0435\u043a (8.3-\u0442\u0430\u0440\u043c\u0430\u049b)."},
gTT(){return"\u0411\u0435\u043b\u0433\u0456 \u0448\u0435\u043a\u0442\u0435\u0443 \u0431\u0430\u0441\u0442\u0430\u043b\u0430\u0442\u044b\u043d \u043e\u0440\u044b\u043d\u0493\u0430 \u0434\u0435\u0439\u0456\u043d\u0433\u0456 \u049b\u0430\u0448\u044b\u049b\u0442\u044b\u049b\u0442\u044b \u043a\u04e9\u0440\u0441\u0435\u0442\u0435 \u043c\u0435?"},
gTS(){return"\u0418\u04d9. \u0411\u0435\u043b\u0433\u0456 \u0431\u0456\u0440 \u0493\u0430\u043d\u0430 \u049b\u0430\u0448\u044b\u049b\u0442\u044b\u049b\u0442\u044b \u043a\u04e9\u0440\u0441\u0435\u0442\u0435\u0434\u0456: \u0431\u0435\u043b\u0433\u0456\u0434\u0435\u043d \u049b\u0430\u0443\u0456\u043f\u0442\u0456 \u0430\u0439\u043c\u0430\u049b\u049b\u0430, \u043e\u0431\u044a\u0435\u043a\u0442\u0456\u0433\u0435 \u043d\u0435\u043c\u0435\u0441\u0435 \u0448\u0435\u043a\u0442\u0435\u0443 \u0431\u0430\u0441\u0442\u0430\u043b\u0430\u0442\u044b\u043d \u043e\u0440\u044b\u043d\u0493\u0430 \u0434\u0435\u0439\u0456\u043d."},
gTV(){return"\u0411\u0435\u043b\u0433\u0456 \u0431\u0435\u043b\u0433\u0456\u043d\u0456\u04a3 \u049b\u0430\u043c\u0442\u0443 \u0430\u0439\u043c\u0430\u0493\u044b\u043d\u044b\u04a3 \u04b1\u0437\u044b\u043d\u0434\u044b\u0493\u044b\u043d \u043a\u04e9\u0440\u0441\u0435\u0442\u0435\u0434\u0456 \u043c\u0435?"},
gTU(){return"\u0416\u043e\u049b. \u049a\u0430\u043c\u0442\u0443 \u0430\u0439\u043c\u0430\u0493\u044b\u043d\u044b\u04a3 \u04b1\u0437\u044b\u043d\u0434\u044b\u0493\u044b 8.2.1 \u043f\u043b\u0430\u0441\u0442\u0438\u043d\u0430\u0441\u044b\u043d\u0434\u0430 \u043a\u04e9\u0440\u0441\u0435\u0442\u0456\u043b\u0433\u0435\u043d."},
gTX(){return"\u0411\u0435\u043b\u0433\u0456 \u049b\u0430\u0443\u0456\u043f\u0442\u0456 \u0430\u0439\u043c\u0430\u049b\u0442\u044b\u04a3 \u043d\u0435\u043c\u0435\u0441\u0435 \u049b\u0430\u043c\u0442\u0443 \u0430\u0439\u043c\u0430\u0493\u044b\u043d\u044b\u04a3 \u04b1\u0437\u044b\u043d\u0434\u044b\u0493\u044b\u043d \u043a\u04e9\u0440\u0441\u0435\u0442\u0435 \u043c\u0435?"},
gTW(){return"\u0418\u04d9. \u0411\u04b1\u043b \u0431\u0435\u043b\u0433\u0456 \u0430\u0439\u043c\u0430\u0493\u044b\u043d\u044b\u04a3 \u043d\u0435\u043c\u0435\u0441\u0435 \u0430\u0443\u0434\u0430\u043d\u044b\u043d\u044b\u04a3 \u04b1\u0437\u044b\u043d\u0434\u044b\u0493\u044b."},
